"""Raw terminal I/O and a cell-oriented ANSI renderer."""
import os
import sys
import tty
import select
import termios
import time
import unicodedata

ESC = '\x1b'
RESET = ESC + '[0m'


def width(char):
    if unicodedata.combining(char):
        return 0
    if char < ' ' or char == '\x7f':
        return 0
    return 2 if unicodedata.east_asian_width(char) in ('W', 'F') else 1


def display_width(text):
    return sum(width(c) for c in text)


def crop(text, limit, ellipsis=False):
    if limit <= 0:
        return ''
    if display_width(text) <= limit:
        return text
    end = '..' if ellipsis and limit >= 2 else ''
    limit -= len(end)
    out = ''
    for char in text:
        cw = width(char)
        if cw > limit:
            break
        out += char
