"""Filesystem entries and reversible file operations."""
import os
import re
import stat
import shutil
from dataclasses import dataclass


def natural(name):
    return tuple((1, int(p), len(p)) if p.isdigit() else (0, p.lower())
                 for p in re.split(r'(\d+)', name))


def extension(name):
    p = name.rfind('.')
    return name[p + 1:].lower() if p > 0 else ''


def size_text(n):
    units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB']
    i = 0
    while n >= 1000 and i < len(units) - 1:
        n //= 1000
        i += 1
    return str(n) + units[i]


def error_text(err):
    if isinstance(err, OSError):
        return f'{err.strerror or os.strerror(err.errno)} (os error {err.errno})'
    return str(err)


@dataclass
class Entry:
    name: str
    path: str
    metadata: object
    directory: bool
    link: bool

    @property
    def ext(self):
        return extension(self.name)


def entries(path, hidden=True, sort_time=False):
    result = []
    with os.scandir(path) as listing:
        for item in listing:
            if not hidden and item.name.startswith('.'):
                continue
            try:
                meta = item.stat(follow_symlinks=False)
                result.append(Entry(item.name, item.path, meta, item.is_dir(), item.is_symlink()))
            except OSError:
                continue
    result.sort(key=lambda e: (not e.directory, natural(e.name), e.name))
    if sort_time:
        result.sort(key=lambda e: (not e.directory, -e.metadata.st_mtime_ns))
    return result


def unused_name(directory, name, is_dir=False, archive=False):
    target = os.path.join(directory, name)
    if not os.path.lexists(target):
        return target
    stem, ext = (name, '') if is_dir or archive else os.path.splitext(name)
    i = 1
    while os.path.lexists(os.path.join(directory, f'{stem}_{i}{ext}')):
        i += 1
    return os.path.join(directory, f'{stem}_{i}{ext}')


def remove(path):
    if os.path.islink(path) or not os.path.isdir(path):
        os.unlink(path)
    else:
        shutil.rmtree(path)


def copy_item(src, dst):
    if os.path.islink(src):
        os.symlink(os.readlink(src), dst)
    elif os.path.isdir(src):
        os.mkdir(dst, stat.S_IMODE(os.stat(src).st_mode))
        for name in os.listdir(src):
            copy_item(os.path.join(src, name), os.path.join(dst, name))
    else:
        shutil.copyfile(src, dst)
        os.chmod(dst, stat.S_IMODE(os.stat(src).st_mode))
