"""Small self-contained reader for the application's configuration format."""
import os
import re
import json
from dataclasses import dataclass, field

COLORS = ['Black', 'Red', 'Green', 'Yellow', 'Blue', 'Magenta', 'Cyan', 'White',
          'LightBlack', 'LightRed', 'LightGreen', 'LightYellow', 'LightBlue',
          'LightMagenta', 'LightCyan', 'LightWhite', 'Rgb', 'AnsiValue']


class ConfigError(Exception):
    pass


@dataclass
class Node:
    value: object
    line: int = 1
    column: int = 1

    def location(self):
        return f' at line {self.line} column {self.column}'


def split_flow(s):
    quote = None
    nesting = 0
    start = 0
    parts = []
    for i, ch in enumerate(s):
        if quote:
            if ch == quote and (i == 0 or s[i - 1] != '\\'):
                quote = None
        elif ch in '\"\'':
            quote = ch
        elif ch in '[{':
            nesting += 1
        elif ch in ']}':
            nesting -= 1
        elif ch == ',' and not nesting:
            parts.append(s[start:i].strip())
            start = i + 1
    if s[start:].strip():
        parts.append(s[start:].strip())
    return parts


def scalar(s, line, column):
    s = s.strip()
    if s.startswith('['):
        if not s.endswith(']'):
            raise ConfigError(f"did not find expected ',' or ']' at line {line + 1} column 1, while parsing a flow sequence at line {line} column {column}")
        return Node([scalar(x, line, column + 1) for x in split_flow(s[1:-1])], line, column)
    if s.startswith('{') and s.endswith('}'):
        v = {}
        for part in split_flow(s[1:-1]):
            if ':' in part:
                k, val = part.split(':', 1)
                v[k.strip().strip('\"\'')] = scalar(val, line, column + s.find(val))
        return Node(v, line, column)
    if s.startswith('!'):
        a = s.split(None, 1)
        val = scalar(a[1], line, column + len(a[0]) + 1) if len(a) > 1 else Node(None, line, column)
        return Node(('tag', a[0][1:], val), line, column)
    if s.startswith('"') and s.endswith('"'):
        try:
            val = json.loads(s)
        except ValueError:
            val = s[1:-1]
    elif s.startswith("'") and s.endswith("'"):
        val = s[1:-1].replace("''", "'")
    else:
        s = re.split(r'\s+#', s, maxsplit=1)[0].strip()
        if s in ('', '~', 'null', 'Null', 'NULL'):
            val = None
        elif s in ('true', 'True', 'TRUE'):
            val = True
        elif s in ('false', 'False', 'FALSE'):
            val = False
        elif re.fullmatch(r'[-+]?\d+', s):
            val = int(s)
        else:
            val = s
    return Node(val, line, column)


def parse_yaml(text):
    lines = []
    for i, s in enumerate(text.splitlines()):
        if not s.strip() or s.lstrip().startswith('#') or s.strip() in ('---', '...'):
            continue
        lines.append((len(s) - len(s.lstrip()), s.lstrip(), i + 1))
    if not lines:
        return Node(None)
    if ':' not in lines[0][1] and not lines[0][1].startswith('- '):
        return scalar(lines[0][1], lines[0][2], lines[0][0] + 1)

    def block(i, indent):
        is_list = lines[i][1].startswith('- ')
        value = [] if is_list else {}
        root = Node(value, lines[i][2], indent + 1)
        while i < len(lines) and lines[i][0] == indent:
            _, s, ln = lines[i]
            if is_list:
                if not s.startswith('- '):
                    break
                tail = s[2:]
                key = None
                col = indent + 3
            else:
                m = re.match(r'([^:]+):(?:\s+(.*)|$)', s)
                if not m:
                    raise ConfigError(f'could not find expected ":" at line {ln + 1} column 1, while scanning a simple key at line {ln} column {indent + 1}')
                key = m.group(1).strip().strip('\"\'')
                tail = m.group(2) or ''
                col = indent + s.find(':') + 2
                if tail:
                    col = indent + s.index(tail, s.find(':') + 1) + 1
                if key in value:
                    raise ConfigError(f'duplicate field `{key}`')
            i += 1
            if not tail.strip() and i < len(lines) and lines[i][0] > indent:
                child, i = block(i, lines[i][0])
            else:
                child = scalar(tail, ln, col)
            if is_list:
                value.append(child)
            else:
                value[key] = child
        return root, i
    return block(0, lines[0][0])[0]


def typename(value):
    if isinstance(value, dict):
        return 'map'
    if isinstance(value, list):
        return 'sequence'
    if value is None:
        return 'unit value'
    if isinstance(value, bool):
        return f'boolean `{str(value).lower()}`'
    if isinstance(value, int):
        return f'integer `{value}`'
    return 'string ' + json.dumps(str(value), ensure_ascii=False)


def invalid(node, expected, path='', location=True):
    raise ConfigError((path + ': ' if path else '') + 'invalid type: ' + typename(node.value)
                      + ', expected ' + expected + (node.location() if location else ''))


@dataclass
class Config:
    default: str = None
    exec: dict = field(default_factory=dict)
    ignore_case: bool = False
    match_vim_exit_behavior: bool = False
    colors: dict = field(default_factory=lambda: dict(dir_fg=14, file_fg=15, symlink_fg=11, dirty_fg=9))
    path: str = None


def color_value(node, name):
    v = node.value
    if isinstance(v, (dict, list)):
        invalid(node, "a YAML tag starting with '!'", 'color.' + name)
    if isinstance(v, tuple) and v[0] == 'tag':
        tag, val = v[1], v[2].value
        if tag == 'AnsiValue' and isinstance(val, int):
            return val
        if tag == 'Rgb':
            if isinstance(val, dict):
                return tuple(val.get(k, Node(0)).value for k in ('r', 'g', 'b'))
            if isinstance(val, list):
                return tuple(x.value for x in val[:3])
        v = tag
    if str(v) not in COLORS:
        variants = ', '.join('`' + x + '`' for x in COLORS)
        raise ConfigError(f'color.{name}: unknown variant `{v}`, expected one of {variants}' + node.location())
    return COLORS.index(str(v))


def read_config(directory):
    cfg = Config()
    path = next((os.path.join(directory, name) for name in ('config.yaml', 'config.yml')
                 if os.path.isfile(os.path.join(directory, name))), None)
    if path is None:
        return cfg, None
    cfg.path = path
    try:
        with open(path, encoding='utf-8') as f:
            root = parse_yaml(f.read())
        if root.value is None:
            return cfg, None
        if not isinstance(root.value, dict):
            invalid(root, 'struct Config', location=False)
        for key, node in root.value.items():
            value = node.value
            if value is None:
                continue
            if key == 'default':
                if isinstance(value, (dict, list, tuple)):
                    invalid(node, 'a string', key)
                cfg.default = str(value).lower() if isinstance(value, bool) else str(value)
            elif key in ('ignore_case', 'match_vim_exit_behavior'):
                if not isinstance(value, bool):
                    invalid(node, 'a boolean', key)
                setattr(cfg, key, value)
            elif key == 'exec':
                if not isinstance(value, dict):
                    invalid(node, 'a map', key)
                for exe, extensions in value.items():
                    if not isinstance(extensions.value, list):
                        invalid(extensions, 'a sequence', 'exec.' + exe)
                    cfg.exec[exe] = [str(x.value) for x in extensions.value]
            elif key == 'color':
                if not isinstance(value, dict):
                    invalid(node, 'struct ConfigColor', key)
                for n in value:
                    if n in cfg.colors:
                        cfg.colors[n] = color_value(value[n], n)
                for n in ('dir_fg', 'file_fg', 'symlink_fg', 'dirty_fg'):
                    if n not in value:
                        raise ConfigError(f'color: missing field `{n}`' + node.location())
        return cfg, None
    except (ConfigError, OSError, UnicodeError) as err:
        fallback = Config(path=path)
        return fallback, ('Cannot read the config file properly.\nError: ' + str(err)
                          + '\nfelix launches with default configuration.\n')
