"""Interactive file-manager state machine and screen composition."""
import os
import re
import sys
import stat
import time
import shlex
import shutil
import tempfile
import subprocess
from dataclasses import dataclass
from .files import entries, size_text, unused_name, copy_item, remove, error_text
from .terminal import Screen, ESC, RESET, crop, display_width
from .archive import extract, NotArchive, ShortArchive


def fg(value):
    if isinstance(value, tuple):
        return f'\x1b[38;2;{value[0]};{value[1]};{value[2]}m'
    return f'\x1b[38;5;{value}m'


@dataclass
class RegisterItem:
    path: str
    name: str
    directory: bool


class App:
    def __init__(self, path, config, trash, terminal, help_text, home, runtime, log=None):
        self.path = path
        self.cfg = config
        self.trash = trash
        self.term = terminal
        self.help_text = help_text
        self.home = home
        self.runtime = runtime
        self.log = log
        self.index = 0
        self.top = 0
        self.hidden = True
        self.sort_time = False
        self.items = []
        self.message = ''
        self.message_error = False
        self.mode = 'normal'
        self.text = ''
        self.pos = 0
        self.prompt = ''
        self.pending = ''
        self.register = '"'
        self.anchor = None
        self.registers = {}
        self.preview = None
        self.horizontal = False
        self.preview_scroll = 0
        self.query = None
        self.search_display = False
        self.search_hit = False
        self.matches = []
        self.help_top = 0
        self.history = []
        self.history_index = 0
        self.visits = {}
        self.undo = []
        self.redo = []
        self.running = True
        self.panic = None
        self.width, self.height = os.get_terminal_size(1)
        self.load(reset=True)
        self.history = [(self.path, 0, 0)]

    @property
    def main_height(self):
        return self.height // 2 if self.preview and self.horizontal else self.height

    @property
    def slots(self):
        return max(1, self.main_height - 3)

    @property
    def selected(self):
        return self.items[self.index] if self.items and 0 <= self.index < len(self.items) else None

    def load(self, reset=False):
        if reset:
            self.index = self.top = 0
            self.query = None
            self.search_display = False
        self.items = entries(self.path, self.hidden, self.sort_time)
        self.index = min(max(0, self.index), max(0, len(self.items) - 1))
        self.top = min(self.top, self.index)
        self.preview_scroll = 0
        self.recalculate_matches()

    def recalculate_matches(self):
        self.matches = []
        if self.query is not None:
            q = self.query.lower() if self.cfg.ignore_case else self.query
            self.matches = [i for i, item in enumerate(self.items)
                            if q in (item.name.lower() if self.cfg.ignore_case else item.name)]

    def say(self, text='', error=False):
        self.message = text
        self.message_error = error

    def fit_layout(self):
        self.index = min(self.index, self.top + self.slots - 1)

    def move(self, delta):
        old = self.index
        new = min(max(0, old + delta), max(0, len(self.items) - 1))
        if new == old:
            return
        if delta > 0:
            self.top = min(max(self.top, new - max(0, self.slots - 4)),
                           max(self.top, len(self.items) - self.slots))
        else:
            self.top = max(0, min(self.top, new - 3))
        self.index = new
        self.preview_scroll = 0

    def go_top(self):
        self.index = self.top = 0
        self.preview_scroll = 0

    def go_bottom(self):
        self.index = max(0, len(self.items) - 1)
        self.top = max(0, len(self.items) - self.slots)
        self.preview_scroll = 0

    def save_visit(self):
        self.visits[self.path] = (self.index, self.top)
        if self.history:
            self.history[self.history_index] = (self.path, self.index, self.top)

    def change_dir(self, target, restore=False, history=True):
        try:
            if not os.path.exists(target):
                self.say('Path does not exist.', True)
                return
            path = os.path.realpath(target)
            # Validate before changing the navigation history.
            entries(path, self.hidden, self.sort_time)
            self.save_visit()
            self.path = path
            self.anchor = None
            self.load(reset=True)
            if restore and path in self.visits:
                i, top = self.visits[path]
                self.index = min(i, max(0, len(self.items) - 1))
                self.top = min(top, self.index)
            self.say()
            if history:
                self.history = self.history[:self.history_index + 1]
                self.history.append((self.path, self.index, self.top))
                self.history_index += 1
        except OSError as err:
            self.say(error_text(err), True)

    def parent(self):
        parent = os.path.dirname(self.path)
        if parent == self.path:
            return
        previous = self.path
        saved = parent in self.visits
        self.change_dir(parent, restore=True)
        if not saved:
            for i, item in enumerate(self.items):
                if item.path == previous:
                    self.index = i
                    self.top = max(0, i - self.slots + 1)
                    break

    def travel(self, direction):
        target = self.history_index + direction
        if target < 0 or target >= len(self.history):
            return
        self.save_visit()
        path, index, top = self.history[target]
        self.change_dir(path, history=False)
        self.history_index = target
        self.index = min(index, max(0, len(self.items) - 1))
        self.top = min(top, self.index)

    def entry_style(self, item):
        key = 'symlink_fg' if item.link else 'dir_fg' if item.directory else 'file_fg'
        return fg(self.cfg.colors[key])

    def status(self):
        if self.search_display and self.query is not None:
            count = len(self.matches)
            return f' /{self.query} - {count} ' + ('matches' if count > 1 else 'match')
        item = self.selected
        if not item:
            return ''
        if item.link:
            target = os.path.realpath(item.path) if os.path.exists(item.path) else '(invalid path)'
            return ' linked to: ' + target
        ext = item.ext
        return (f' {self.index + 1}/{len(self.items)} ' + (ext + ' ' if ext else '')
                + size_text(item.metadata.st_size) + ' ' + format(stat.S_IMODE(item.metadata.st_mode), 'o'))

    def preview_lines(self, limit):
        item = self.selected
        if not item:
            return []
        if item.directory:
            try:
                files = entries(item.path, self.hidden, self.sort_time)
                return [(('└ ' if i == len(files) - 1 else '├ ') + e.name, self.entry_style(e))
                        for i, e in enumerate(files)]
            except OSError:
                return [('(directory not readable)', '')]
        try:
            with open(item.path, 'rb') as f:
                data = f.read(4 * 1024 * 1024)
            if data.startswith((b'\x89PNG', b'GIF87a', b'GIF89a', b'\xff\xd8\xff', b'BM')):
                return [('(image preview is not available)', '')]
            text = data.decode('utf-8')
            if '\x00' in text:
                return [('(binary file)', '')]
            lines = text.splitlines()
            result = []
            for line in lines:
                line = re.sub(r'\x1b\[[0-9;?]*[A-Za-z]', '', line).expandtabs(4)
                result.append((line, ''))
            return result
        except UnicodeError:
            return [('(binary file)', '')]
        except OSError:
            return [('(file not readable)', '')]

    def render(self):
        screen = Screen(self.width, self.height)
        if self.mode == 'help':
            lines = self.help_text.splitlines()
            for row, line in enumerate(lines[self.help_top:self.help_top + self.height - 1]):
                screen.text(0, row, line)
            if self.help_top + self.height - 1 < len(lines):
                screen.text(0, self.height - 1, '...')
            return screen.render((0, 0, False))
        main_w = self.width // 2 if self.preview and not self.horizontal else self.width
        screen.text(0, 0, crop(' ' + self.path, main_w, True), fg(6))
        mark = self.mode in ('normal', 'pending', 'rename', 'confirm') or (self.mode == 'search' and self.search_hit)
        for row, i in enumerate(range(self.top, min(len(self.items), self.top + self.slots)), 2):
            item = self.items[i]
            selected = self.anchor is not None and min(self.anchor, self.index) <= i <= max(self.anchor, self.index)
            style = self.entry_style(item)
            if selected:
                style = '\x1b[7m' + style
            name_width = max(0, main_w - 19)
            name = crop(item.name, name_width, True)
            screen.text(2, row, name, style, name_width)
            date = time.strftime('%Y-%m-%d %H:%M', time.localtime(item.metadata.st_mtime))
            if main_w >= 19:
                if selected:
                    screen.text(main_w - 16, row, date, '\x1b[7m')
                else:
                    screen.text(main_w - 17, row, ' ' + date, self.entry_style(item))
            if self.query and self.mode in ('normal', 'search') and i in self.matches:
                # Search is indicated in the footer; selection remains the simple arrow.
                pass
        if mark:
            y = 2 + self.index - self.top if self.items else 2
            screen.text(0, y, '>')
        if self.items:
            screen.fill(self.main_height - 1, '\x1b[7m')
            screen.text(0, self.main_height - 1, self.status(), '\x1b[7m')
        if self.preview:
            if self.horizontal:
                px, py = 0, self.main_height + 1
            else:
                px, py = main_w + 1, 2
            pw = max(0, self.width - px)
            ph = self.height - py if self.horizontal else self.height - py - 1
            if self.preview == 'file':
                item = self.selected
                if item and not self.horizontal:
                    screen.text(px, 0, crop('[' + item.name + ']', pw, True), fg(6))
                lines = self.preview_lines(ph)
                self.preview_scroll = min(self.preview_scroll, max(0, len(lines) - 1))
                for j, (line, style) in enumerate(lines[self.preview_scroll:self.preview_scroll + ph]):
                    screen.text(px, py + j, line, style, pw)
            elif self.preview == 'registers':
                keys = ['"'] + [str(i) for i in range(10)] + [chr(i) for i in range(97, 123)]
                lines = ['"' + key + ' ' + ' '.join(x.name for x in self.registers[key])
                         for key in keys if self.registers.get(key)]
                for j, line in enumerate(lines[:ph]):
                    screen.text(px, py + j, line, '', pw)
        cursor = (0, 2 + self.index - self.top, False)
        if self.mode in ('insert', 'mkdir', 'rename', 'command', 'search', 'jump'):
            shown = self.prompt + self.text
            screen.text(1, 1, shown)
            cursor = (1 + display_width(self.prompt + self.text[:self.pos]), 1, True)
        elif self.mode == 'pending':
            screen.text(1, 1, self.pending)
            cursor = (1 + len(self.pending), 1, True)
        elif self.message:
            screen.text(1, 1, self.message, fg(9) if self.message_error else '')
        return screen.render(cursor)

    def begin(self, mode, prefix, text=''):
        self.mode = mode
        self.prompt = prefix
        self.text = text
        self.pos = len(text)
        self.say()
        self.search_hit = False

    def cancel_input(self):
        self.mode = 'normal'
        self.pending = ''
        self.register = '"'
        self.say()

    def input_key(self, key):
        if self.mode == 'command' and getattr(self, 'paste_register', False):
            self.paste_register = False
            values = self.registers.get(key, [])
            self.insert_text(' '.join(v.name for v in values))
            return
        if key == 'Escape':
            self.cancel_input()
            return
        if key == 'Enter':
            self.accept_input()
            return
        if key == 'Left':
            self.pos = max(0, self.pos - 1)
        elif key == 'Right':
            self.pos = min(len(self.text), self.pos + 1)
        elif key == 'Backspace':
            if self.pos > 0:
                self.text = self.text[:self.pos - 1] + self.text[self.pos:]
                self.pos -= 1
        elif key == 'Delete':
            self.text = self.text[:self.pos] + self.text[self.pos + 1:]
        elif key == 'Ctrl-r' and self.mode == 'command':
            self.paste_register = True
        elif key == 'Tab':
            self.complete()
        elif len(key) == 1:
            self.insert_text(key)
        elif key.startswith(('Alt-', 'Ctrl-')) and len(key.split('-', 1)[1]) == 1:
            self.insert_text(key.split('-', 1)[1])
        if self.mode == 'search':
            self.query = self.text
            self.recalculate_matches()
            if self.matches:
                self.index = self.matches[0]
                self.top = self.index
                self.preview_scroll = 0
                self.search_hit = True

    def insert_text(self, text):
        self.text = self.text[:self.pos] + text + self.text[self.pos:]
        self.pos += len(text)

    def complete(self):
        if self.mode != 'command':
            return
        # Only paths after cd are completed. An ordinary command is left untouched.
        if not self.text.startswith('cd '):
            return
        typed = self.text[3:]
        expanded = os.path.expanduser(typed)
        parent, prefix = os.path.split(expanded)
        full_parent = parent if os.path.isabs(parent) else os.path.join(self.path, parent)
        try:
            possibilities = [x for x in os.listdir(full_parent) if x.startswith(prefix) and os.path.isdir(os.path.join(full_parent, x))]
            if len(possibilities) == 1:
                added = possibilities[0][len(prefix):] + '/'
                self.text += added
                self.pos = len(self.text)
        except OSError:
            pass

    def accept_input(self):
        mode, text = self.mode, self.text
        self.mode = 'normal'
        self.say()
        try:
            if mode == 'insert':
                target = os.path.join(self.path, text)
                with open(target, 'xb'):
                    pass
                self.load()
            elif mode == 'mkdir':
                os.mkdir(os.path.join(self.path, text))
                self.load()
            elif mode == 'rename':
                item = self.selected
                if item:
                    target = os.path.join(self.path, text)
                    before = item.path
                    os.rename(before, target)
                    self.record(('RENAME', [(before, target)]))
                    self.load()
            elif mode == 'command':
                self.command(text)
            elif mode == 'search':
                self.query = text
                self.search_display = True
                self.recalculate_matches()
            elif mode == 'jump':
                if not text.strip():
                    self.change_dir(self.home)
                else:
                    p = subprocess.run(['zoxide', 'query'] + text.split(), capture_output=True, text=True)
                    if p.returncode == 0:
                        self.change_dir(p.stdout.strip())
                    else:
                        self.say('No match found.', True)
        except OSError as err:
            self.say(error_text(err), True)
        except ValueError as err:
            self.say(str(err), True)

    def command(self, text):
        if text == 'q':
            self.quit(False)
        elif text == 'h':
            self.mode = 'help'
            self.help_top = 0
        elif text == 'e':
            self.anchor = None
            self.load(reset=True)
        elif text == 'reg':
            self.preview = 'registers'
            self.fit_layout()
        elif text == 'config':
            if self.cfg.path:
                self.change_dir(os.path.dirname(self.cfg.path))
            else:
                self.say('Cannot find the config path.', True)
        elif text == 'trash':
            self.change_dir(self.trash)
        elif text == 'empty':
            self.mode = 'confirm'
            self.say('Are you sure to empty the trash directory? (if yes: y)')
        elif text == 'cd' or text.startswith('cd '):
            dest = text[2:].strip() or self.home
            if dest == '~' or dest.startswith('~/'):
                dest = self.home + dest[1:]
            if len(dest) >= 2 and dest[0] in '\"\'' and dest[-1] == dest[0]:
                dest = dest[1:-1]
            self.change_dir(os.path.join(self.path, dest))
        elif text:
            self.run_external(text)

    def run_external(self, text):
        self.term.suspend()
        try:
            subprocess.run(text, shell=True, cwd=self.path)
        except OSError:
            pass
        finally:
            self.term.resume()
        self.load()

    def open_item(self, new_window=False):
        item = self.selected
        if not item:
            return
        if item.directory and not new_window:
            self.change_dir(item.path)
            return
        command = None
        for program, extensions in self.cfg.exec.items():
            if item.ext in extensions:
                command = program
                break
        if not command and new_window:
            self.say('No exec configuration', True)
            return
        command = command or self.cfg.default or os.environ.get('EDITOR')
        if not command:
            self.say('$EDITOR may not be set, or config file may be invalid.', True)
            return
        try:
            args = shlex.split(command) + [item.path]
            if new_window:
                subprocess.Popen(args, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            else:
                self.term.suspend()
                try:
                    subprocess.run(args)
                finally:
                    self.term.resume()
            self.say()
            self.load()
        except (OSError, ValueError):
            self.say('$EDITOR may not be set, or config file may be invalid.', True)

    def selected_items(self):
        if not self.items:
            return []
        if self.anchor is None:
            return [self.selected]
        start, end = sorted([self.anchor, self.index])
        return self.items[start:end + 1]

    def store_register(self, values, reg, delete=False):
        if reg == '_':
            return
        self.registers['"'] = list(values)
        if reg == '"':
            if delete:
                for i in range(9, 1, -1):
                    if str(i - 1) in self.registers:
                        self.registers[str(i)] = list(self.registers[str(i - 1)])
                self.registers['1'] = list(values)
            else:
                self.registers['0'] = list(values)
        elif reg.isupper():
            self.registers.setdefault(reg.lower(), []).extend(values)
        else:
            self.registers[reg] = list(values)

    def yank(self, reg='"'):
        items = self.selected_items()
        if not items:
            return
        vals = [RegisterItem(e.path, e.name, e.directory) for e in items]
        self.store_register(vals, reg)
        self.anchor = None
        self.say('1 item yanked.' if len(vals) == 1 else f'{len(vals)} items yanked')

    def record(self, op):
        self.undo.append(op)
        self.redo.clear()

    def delete(self, reg='"'):
        items = self.selected_items()
        if not items:
            return
        pairs = []
        vals = []
        try:
            for item in items:
                target = unused_name(self.trash, str(int(time.time())) + '_' + item.name, item.directory)
                try:
                    os.rename(item.path, target)
                except OSError:
                    copy_item(item.path, target)
                    remove(item.path)
                pairs.append((item.path, target))
                vals.append(RegisterItem(target, item.name, item.directory))
            self.store_register(vals, reg, delete=True)
            self.record(('DELETE', pairs))
            self.anchor = None
            self.load()
            self.say(f'{len(vals)} ' + ('item' if len(vals) == 1 else 'items') + ' deleted. [0.00s]')
        except OSError as err:
            self.anchor = None
            self.load()
            self.say(error_text(err), True)

    def put(self, reg='"'):
        values = self.registers.get(reg.lower(), [])
        if not values:
            return
        pairs = []
        try:
            for item in values:
                target = unused_name(self.path, item.name, item.directory)
                # Prevent an unbounded self-copy when pasting a directory into itself.
                if item.directory and os.path.commonpath([os.path.realpath(item.path), os.path.realpath(target)]) == os.path.realpath(item.path):
                    raise OSError(22, 'Invalid argument')
                copy_item(item.path, target)
                pairs.append((item.path, target))
            self.record(('PUT', pairs))
            self.load()
            self.say(f'{len(pairs)} ' + ('item' if len(pairs) == 1 else 'items') + ' inserted. [0.00s]')
        except OSError as err:
            self.load()
            self.say(error_text(err), True)

    def undo_redo(self, redo=False):
        source = self.redo if redo else self.undo
        target = self.undo if redo else self.redo
        if not source:
            self.say('No operations left.', True)
            return
        name, pairs = source.pop()
        try:
            for old, new in pairs:
                if name == 'RENAME':
                    os.rename(old if redo else new, new if redo else old)
                elif name == 'PUT':
                    if redo:
                        copy_item(old, new)
                    else:
                        remove(new)
                elif name == 'DELETE':
                    if redo:
                        remove(old)
                    else:
                        copy_item(new, old)
            target.append((name, pairs))
            self.load()
            self.say(('REDONE: ' if redo else 'UNDONE: ') + name)
            if not self.items:
                self.say()
        except OSError as err:
            self.load()
            self.say(error_text(err), True)

    def bulk_rename(self):
        selected = self.selected_items()
        editor = self.cfg.default or os.environ.get('EDITOR')
        if not editor:
            self.say('$EDITOR may not be set, or config file may be invalid.', True)
            self.anchor = None
            return
        temp = None
        try:
            fd, temp = tempfile.mkstemp(prefix='felix-', suffix='.txt')
            with os.fdopen(fd, 'w') as f:
                f.write('\n'.join(i.name for i in selected) + '\n')
            self.term.suspend()
            try:
                subprocess.run(shlex.split(editor) + [temp])
            finally:
                self.term.resume()
            with open(temp) as f:
                newnames = f.read().splitlines()
            pairs = []
            if len(newnames) == len(selected):
                for item, name in zip(selected, newnames):
                    if name and item.name != name:
                        dst = os.path.join(self.path, name)
                        os.rename(item.path, dst)
                        pairs.append((item.path, dst))
            if pairs:
                self.record(('RENAME', pairs))
            self.anchor = None
            self.load()
        except OSError as err:
            self.say(error_text(err), True)
            self.anchor = None
        finally:
            if temp and os.path.exists(temp):
                os.unlink(temp)

    def unpack(self):
        if not self.selected:
            return
        try:
            extract(self.selected.path)
            self.load()
            self.say('Unpacked. [0.00s]')
        except ShortArchive as err:
            self.panic = str(err)
            self.running = False
        except (OSError, NotArchive, ValueError, EOFError) as err:
            self.say(error_text(err), True)
        except Exception as err:
            self.say(str(err), True)

    def quit(self, last_directory):
        if last_directory and os.environ.get('SHELL_PID'):
            try:
                with open(os.path.join(self.runtime, os.environ['SHELL_PID']), 'w') as f:
                    f.write(self.path)
            except OSError:
                pass
        self.running = False

    def pending_key(self, key):
        if key == 'Escape':
            self.cancel_input()
            return
        p = self.pending
        if p == '"':
            if len(key) == 1 and (key.isascii() and key.isalnum() or key in ('_', '"')):
                self.register = key
                self.pending += key
            else:
                self.cancel_input()
            return
        if p.startswith('"') and len(p) == 2:
            if key == 'p':
                self.mode = 'normal'
                self.say()
                self.put(self.register)
                self.register = '"'
            elif key in ('d', 'y'):
                if self.anchor is not None:
                    self.mode = 'normal'
                    self.say()
                    (self.delete if key == 'd' else self.yank)(self.register)
                    self.register = '"'
                else:
                    self.pending += key
            else:
                self.cancel_input()
            return
        reg = self.register
        self.mode = 'normal'
        self.pending = ''
        self.register = '"'
        self.say()
        if p[-1:] == 'd' and key == 'd':
            self.delete(reg)
        elif p[-1:] == 'y' and key == 'y':
            self.yank(reg)
        elif p == 'g' and key == 'g':
            self.go_top()
        elif p == 'Z' and key in ('Z', 'Q'):
            self.quit((key == 'Z') == self.cfg.match_vim_exit_behavior)

    def help_key(self, key):
        last = max(0, len(self.help_text.splitlines()) - self.height + 1)
        if key in ('j', 'Down'):
            self.help_top = min(last, self.help_top + 1)
        elif key in ('k', 'Up'):
            self.help_top = max(0, self.help_top - 1)
        elif key == 'Ctrl-d':
            self.help_top = min(last, self.help_top + self.height // 2)
        elif key == 'Ctrl-u':
            self.help_top = max(0, self.help_top - self.height // 2)
        else:
            self.mode = 'normal'

    def handle(self, key):
        if key == 'EOF':
            self.running = False
            return
        if self.mode == 'help':
            self.help_key(key)
            return
        if self.mode in ('insert', 'mkdir', 'rename', 'command', 'search', 'jump'):
            self.input_key(key)
            return
        if self.mode == 'pending':
            self.pending_key(key)
            return
        if self.mode == 'confirm':
            self.mode = 'normal'
            self.say()
            if key == 'y':
                try:
                    for name in os.listdir(self.trash):
                        remove(os.path.join(self.trash, name))
                    self.load()
                    self.say('Trash dir emptied')
                except OSError as err:
                    self.say(error_text(err), True)
            return
        if key in ('j', 'Down'):
            self.move(1)
        elif key in ('k', 'Up'):
            self.move(-1)
        elif key == 'Ctrl-d':
            self.move(self.main_height // 2)
        elif key == 'Ctrl-u':
            self.move(-self.main_height // 2)
        elif key in ('h', 'Left'):
            self.parent()
        elif key in ('l', 'Right', 'Enter'):
            self.open_item()
        elif key == 'o':
            self.open_item(True)
        elif key == 'G':
            self.go_bottom()
        elif key in ('g', 'Z', '"'):
            self.mode = 'pending'
            self.pending = key
            self.say()
        elif key in ('d', 'y'):
            if self.anchor is not None:
                (self.delete if key == 'd' else self.yank)()
            else:
                self.mode = 'pending'
                self.pending = key
                self.say()
        elif key == 'p':
            self.say()
            self.put()
        elif key == 'u':
            self.undo_redo()
        elif key == 'Ctrl-r':
            self.undo_redo(True)
        elif key == 'V':
            self.say()
            self.anchor = self.index if self.anchor is None else None
        elif key == 'Escape':
            self.anchor = None
            self.say()
        elif key == 'i':
            self.begin('insert', 'New file: ')
        elif key == 'I':
            self.begin('mkdir', 'New directory: ')
        elif key == 'c':
            if self.anchor is not None:
                self.bulk_rename()
            elif self.selected:
                self.begin('rename', 'New name: ', self.selected.name)
        elif key == ':':
            self.begin('command', ':')
        elif key == '/':
            self.begin('search', '/')
        elif key in ('n', 'N'):
            if self.matches:
                if key == 'n':
                    choices = [i for i in self.matches if i > self.index]
                    self.index = choices[0] if choices else self.matches[0]
                else:
                    choices = [i for i in self.matches if i < self.index]
                    self.index = choices[-1] if choices else self.matches[-1]
                self.top = self.index
                self.preview_scroll = 0
        elif key == 'v':
            self.say()
            self.preview = 'file' if self.preview is None else None
            self.fit_layout()
        elif key == 's':
            self.say()
            self.horizontal = not self.horizontal
            self.fit_layout()
        elif key == 'Alt-j':
            self.preview_scroll += 1
        elif key == 'Alt-k':
            self.preview_scroll = max(0, self.preview_scroll - 1)
        elif key == 'Backspace':
            self.say()
            self.hidden = not self.hidden
            self.load(reset=True)
        elif key == 't':
            self.say()
            self.sort_time = not self.sort_time
            self.load(reset=True)
        elif key == 'Ctrl-o':
            self.travel(-1)
        elif key == 'Tab':
            self.travel(1)
        elif key == 'z':
            if shutil.which('zoxide'):
                self.begin('jump', 'z ')
            else:
                self.say('zoxide not found.', True)
        elif key == 'e':
            self.unpack()

    def run(self):
        self.term.start()
        try:
            os.write(1, self.render())
            while self.running:
                key = self.term.key()
                try:
                    width, height = os.get_terminal_size(1)
                    resized = (width, height) != (self.width, self.height)
                    if resized:
                        self.width, self.height = width, height
                        self.fit_layout()
                except OSError:
                    resized = False
                if key is not None:
                    try:
                        self.handle(key)
                    except OSError as err:
                        self.mode = 'normal'
                        self.say(error_text(err), True)
                if self.running and (key is not None or resized):
                    os.write(1, self.render())
        finally:
            self.term.close()
        if self.panic:
            sys.stderr.write('Panic: ' + self.panic + '\nError: felix panicked\n')
