"""Command-line startup, environment paths, and application lifetime."""
import os
import sys
import time
from importlib.resources import files
from .config import read_config
from .terminal import Terminal
from .app import App


def resource(name):
    return files('felix').joinpath(name).read_text(encoding='utf-8')


def main():
    args = sys.argv[1:]
    help_text = resource('help.txt')
    logging = False
    path = None
    if len(args) == 1:
        if args[0] in ('--help', '-h'):
            sys.stdout.write(help_text)
            return
        if args[0] == '--init':
            sys.stdout.write(resource('init.txt'))
            return
        if args[0] in ('--log', '-l'):
            logging = True
        else:
            path = args[0]
    elif len(args) == 2 and args[0] in ('--log', '-l'):
        logging = True
        path = args[1]
    elif args:
        sys.stdout.write(help_text)
        return
    if path is not None:
        if not os.path.exists(path):
            sys.stdout.write('\n')
            sys.stderr.write('Invalid path: ' + path + '\n`fx -h` shows help.\n')
            return
        if not os.path.isdir(path):
            sys.stderr.write('Path should be directory.\n`fx -h` shows help.\n')
            return
    try:
        path = os.path.realpath(path or os.getcwd())
    except OSError as err:
        sys.stderr.write('Error: ' + str(err) + '\n')
        return
    home = os.environ.get('HOME', os.path.expanduser('~'))
    cfgdir = os.path.join(os.environ.get('XDG_CONFIG_HOME') or os.path.join(home, '.config'), 'felix')
    datadir = os.path.join(os.environ.get('XDG_DATA_HOME') or os.path.join(home, '.local', 'share'), 'felix')
    trash = os.path.join(datadir, 'Trash')
    runtime = os.path.join(os.environ.get('XDG_RUNTIME_DIR') or os.environ.get('TMPDIR') or '/tmp', 'felix')
    log = None
    try:
        for directory in (cfgdir, trash, runtime):
            os.makedirs(directory, exist_ok=True)
        cfg, warning = read_config(cfgdir)
        if warning:
            sys.stderr.write(warning)
        if logging:
            logdir = os.path.join(datadir, 'log')
            os.makedirs(logdir, exist_ok=True)
            log = open(os.path.join(logdir, time.strftime('%Y-%m-%d-%H-%M-%S.log')), 'w')
            log.write(time.strftime('%H:%M:%S') + ' [INFO] ===START===\n')
            log.flush()
        try:
            columns, rows = os.get_terminal_size(1)
            if columns == 0 or rows == 0:
                raise OSError()
        except OSError:
            sys.stderr.write('Error: Cannot detect terminal size\n')
            return
        term = Terminal()
        app = App(path, cfg, trash, term, help_text, home, runtime, log)
        app.run()
    except (OSError, ValueError) as err:
        sys.stderr.write('Error: ' + str(err) + '\n')
    finally:
        if log:
            log.close()
